def loop_cables(n, cables):
    parent = list(range(n))

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        while parent[x] != root:
            parent[x], x = root, parent[x]
        return root

    spare = []
    for i, (a, b) in enumerate(cables):
        ra, rb = find(a), find(b)
        if ra == rb:
            spare.append(i)
        else:
            parent[ra] = rb
    return spare

